import{z as d,x as o,o as A,c as p,q as t,j as r,D as E,d as n,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"深度定价收束","description":"","frontmatter":{"title":"深度定价收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dp-map.md","filePath":"quant/dp-map.md","lastUpdated":1791413859000}'),s={name:"quant/dp-map.md"};function h(u,a,m,f,D,c){const B=o("Mermaid");return A(),p("div",null,[a[2]||(a[2]=t('<h1 id="深度定价收束" tabindex="-1">深度定价收束 <a class="header-anchor" href="#深度定价收束" aria-label="Permalink to &quot;深度定价收束&quot;">​</a></h1><div class="epigraph"><p>深度学习没有取消金融模型的任何一问——测度是谁、模拟器可信吗、失效谁先知道——它只是把答案从方程搬进了管线；这门课的任务是搬家之后每个问题仍有人回答。</p><footer>—— 据 Buehler, Gonon, Teichmann and Wood, Quantitative Finance, 2019；Ruf and Wang, Journal of Computational Finance, 2020（综述）整理</footer></div><p><a href="/quant/dp-benchmarks-datasets">上一课</a>把基准、数据集与协议钉成底座。本课收束全课程：把八课重排成一张地图，重申贯穿口径，交还边界。下一门课程会从信号与数据的接口接走这套管线，那是另类数据的事。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>八课要收的是两条主线。信号单元（前三课）给的是经济价值口径：<a href="/quant/dp-deep-vol">深度波动率</a>对 HAR 与 QLIKE 交卷，<a href="/quant/dp-deep-micro-signals">深度微观信号</a>对线性基线与冲击成本交卷，<a href="/quant/dp-rl-execution-deep">RL 执行</a>对解析基线与短缺分布交卷——三课共享一个判据：扣掉基线与成本之后剩下的才叫增量。定价与验证单元（后五课）给的是测度与模拟器口径：<a href="/quant/dp-generative-calibration">生成校准</a>立起测度纪律与两本误差账，<a href="/quant/dp-deep-hedging-deep">深度对冲深化</a>消费冻结的模拟器并把 \\(\\rho\\) 钉成产品参数，<a href="/quant/dp-model-risk">模型风险</a>与<a href="/quant/dp-benchmarks-datasets">基准数据集</a>把验证制度化。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是收束而不新增：把八课按「信号单元—定价与验证单元」两条主线重排成一张读序地图，每课只保留三样东西——它交卷的判据、它消费的上游、它留给下游的接口；各课结论仍以各自课内的验收为准，本课不重新计分。地图之后重申三条贯穿口径，边界只做重申、不做扩展。</p><h3 id="一张地图" tabindex="-1">一张地图 <a class="header-anchor" href="#一张地图" aria-label="Permalink to &quot;一张地图&quot;">​</a></h3><p>按读序：</p><ul><li><a href="/quant/dp-deep-vol">深度波动率模型</a>：\\(\\mathbb{P}\\) 测度信号，基线先于架构。</li><li><a href="/quant/dp-deep-micro-signals">深度微观结构信号</a>：增量对成本结算，快照流与事件流并行。</li><li><a href="/quant/dp-rl-execution-deep">强化学习执行的深入</a>：环境构造决定策略上限，解析基线同台。</li><li><a href="/quant/dp-generative-calibration">生成模型校准市场</a>：代理与生成两形态，测度纪律先行。</li><li><a href="/quant/dp-deep-hedging-deep">深度对冲的深化</a>：整本账、工具集、\\(\\rho\\) 即产品。</li><li><a href="/quant/dp-model-risk">模型风险</a>：配方即模型，判据前置。</li><li><a href="/quant/dp-benchmarks-datasets">基准与数据集</a>：配对表、时点纪律、显著性。</li></ul>',10)),(A(),r(l,null,{default:E(()=>[i(B,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E5%8D%95%E5%85%83%EF%BC%9A%E7%BB%8F%E6%B5%8E%E4%BB%B7%E5%80%BC%E5%8F%A3%E5%BE%84%22%5D%0A%20%20%20%20V%5B%22%E6%B7%B1%E5%BA%A6%E6%B3%A2%E5%8A%A8%E7%8E%87%22%5D%20--%3E%20M%5B%22%E6%B7%B1%E5%BA%A6%E5%BE%AE%E8%A7%82%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20%20%20M%20--%3E%20R%5B%22RL%20%E6%89%A7%E8%A1%8C%22%5D%0A%20%20end%0A%20%20subgraph%20PR%5B%22%E5%AE%9A%E4%BB%B7%E4%B8%8E%E9%AA%8C%E8%AF%81%E5%8D%95%E5%85%83%EF%BC%9A%E6%B5%8B%E5%BA%A6%E4%B8%8E%E6%A8%A1%E6%8B%9F%E5%99%A8%E5%8F%A3%E5%BE%84%22%5D%0A%20%20%20%20G%5B%22%E7%94%9F%E6%88%90%E6%A0%A1%E5%87%86%22%5D%20--%3E%20H%5B%22%E6%B7%B1%E5%BA%A6%E5%AF%B9%E5%86%B2%E6%B7%B1%E5%8C%96%22%5D%0A%20%20%20%20H%20--%3E%20MR%5B%22%E6%A8%A1%E5%9E%8B%E9%A3%8E%E9%99%A9%22%5D%0A%20%20%20%20MR%20--%3E%20BM%5B%22%E5%9F%BA%E5%87%86%E4%B8%8E%E6%95%B0%E6%8D%AE%E9%9B%86%22%5D%0A%20%20end%0A%20%20SIG%20--%3E%20PR%0A%20%20PR%20--%3E%20NEXT%5B%22%E5%8F%A6%E7%B1%BB%E6%95%B0%E6%8D%AE%E8%AF%BE%E7%A8%8B%E6%8E%A5%E8%B5%B0%E6%95%B0%E6%8D%AE%E4%B8%8E%E4%BF%A1%E5%8F%B7%E6%8E%A5%E5%8F%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"把八课压成一个视角：深度学习把「模型」的边界从方程外扩到管线——数据窗口、表示、损失、模拟器、种子都是模型的一部分。三条贯穿口径由此而来。基线先于架构：HAR、OFI、TWAP/AC、参数校准、BS delta，每个任务的第一对照都是解析或线性时代留下的最强基线，深度增量在它们之上计量。测度先于用途：\\(\\mathbb{P}\\) 信号、\\(\\mathbb{Q}\\) 定价、对冲在哪个测度下训练，交付前写明，混用即系统性错误。验证先于部署：冻结、留出、支撑检测、多种子与显著性、台账与失效判据——部署是验证的下游，不是研究的下游。",-1)),a[5]||(a[5]=e("p",null,"若问三条口径各自把守管线的哪一道关口，可以画成这样：",-1)),(A(),r(l,null,{default:E(()=>[i(B,{id:"mermaid-72",class:"mermaid",graph:"flowchart%20LR%0A%20%20DATA%5B%22%E6%95%B0%E6%8D%AE%E7%AA%97%E5%8F%A3%E4%B8%8E%E6%B5%8B%E5%BA%A6%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20REP%5B%22%E8%A1%A8%E7%A4%BA%E4%B8%8E%E7%BD%91%E7%BB%9C%22%5D%0A%20%20REP%20--%3E%20LOSS%5B%22%E6%8D%9F%E5%A4%B1%E4%B8%8E%E5%9F%BA%E7%BA%BF%E5%AF%B9%E7%85%A7%22%5D%0A%20%20LOSS%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E5%99%A8%E4%B8%8E%E7%A7%8D%E5%AD%90%22%5D%0A%20%20SIM%20--%3E%20VAL%5B%22%E5%86%BB%E7%BB%93%E3%80%81%E7%95%99%E5%87%BA%E4%B8%8E%E6%98%BE%E8%91%97%E6%80%A7%E6%A3%80%E9%AA%8C%22%5D%0A%20%20VAL%20--%3E%20DEP%5B%22%E9%83%A8%E7%BD%B2%E4%B8%8E%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20MEAS%5B%22%E6%B5%8B%E5%BA%A6%E5%85%88%E4%BA%8E%E7%94%A8%E9%80%94%22%5D%20-.%E6%8A%8A%E5%AE%88.-%20DATA%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E5%85%88%E4%BA%8E%E6%9E%B6%E6%9E%84%22%5D%20-.%E6%8A%8A%E5%AE%88.-%20LOSS%0A%20%20VER%5B%22%E9%AA%8C%E8%AF%81%E5%85%88%E4%BA%8E%E9%83%A8%E7%BD%B2%22%5D%20-.%E6%8A%8A%E5%AE%88.-%20VAL%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">「模型的边界外扩到管线」翻译成大白话：评价一个深度定价系统时，被评价的对象不只是网络结构，而是连同数据窗口、损失函数、模拟器和随机种子打包在一起的整体——换个种子结论就翻转的系统，和参数不稳健的方程模型一样不合格。</span></p><p><span class="marginnote">Ruf 与 Wang 的综述清点了上百篇神经网络定价与对冲论文，比较协议几乎互不兼容。本课程的口径——基线、测度、冻结、台账——正是为「跨论文比较不可信」这个事实准备的。</span></p><p><span class="marginnote">「基线先于架构」可以想象成新药试验里的安慰剂对照组：HAR、TWAP、BS delta 就是深度模型的「安慰剂」。深度方法只有在明显好过这些老办法时才值得上线——否则多出来的复杂度本身就是成本和失效点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束课不新增机制，边界重申三条。其一，深度增量是条件性的：它兑现于约束更真实、维度更高、解析形式够不着的地方，不是无条件超越；基线够用的地方不必上网络。其二，增量要同时过统计与经济两道折价，基点级改进覆盖不了成本就不算数。其三，管线每层都是失效点：数据、生成器、网络、\\(\\rho\\) 的选择——深度不减少模型风险，只改变它的形状；治理的问询不变，变的只是被问询的对象。深钻层继续向后延伸：下一门课程带着这套管线口径走进另类数据。</p><p><span class="marginnote">「两道折价」代入数字感受一下：某策略年化超额 25 个基点，统计上刚好显著；可双边成本吃掉 15 个基点、容量限制再摊薄 8 个基点，只剩 2 个基点——撑不起一套深度管线的维护成本，此时用基线方案才是理性选择。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两条主线：信号单元的经济价值口径；定价与验证单元的测度与模拟器口径。</li><li>一个视角：模型的边界外扩到管线，数据、损失、模拟器与种子都是模型。</li><li>三条口径：基线先于架构、测度先于用途、验证先于部署。</li><li>增量是条件性的：在解析够不着的维度兑现，过不了两道折价就不算数。</li><li>出处：Buehler, Gonon, Teichmann and Wood, <em>QF</em>, 2019；Ruf and Wang, <em>Journal of Computational Finance</em>, 2020；Wiese et al., <em>Quantitative Finance</em>, 2020。</li></ul>',8))])}const b=d(s,[["render",h]]);export{q as __pageData,b as default};
